class Node {
  public Integer value;
  public Node left;
  public Node right;

  public Node(Integer value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }
}

class Invert {
  public Node solve(Node root) {
    if (root == null) {
      return null;
    }
    Node temp = root.left;
    root.left = solve(root.right);
    root.right = solve(temp);
    return root;
  }
}

